using System;using System.IO;using System.Linq;using System.Text;using System.Diagnostics;using System.Threading;using System.Collections.Generic;using System.Text.RegularExpressions;
namespace PZ3D {
 sealed class PlaytimeStore {public int version=1,reminderMinutes=60;public string session,reminderDay;public double totalSeconds,sessionSeconds,nextReminder=60;public long lastTicks;public bool running;public Dictionary<string,double> days=new Dictionary<string,double>();}
 sealed class PlaytimeRequest {public string game,nonce;public long created;}
 static class PlaytimeTracker {
  static string FileAt(string data){return Path.Combine(data,"playtime","time.json");}
  static PlaytimeStore Read(string file){var s=LauncherNativeState.Read(file,()=>new PlaytimeStore());if(s==null||s.version!=1||s.days==null||s.days.Count>4000||s.totalSeconds<0||s.sessionSeconds<0||s.reminderMinutes<0||s.reminderMinutes>480||s.totalSeconds>1e10)throw new Exception("游玩计时记录无效，未覆盖。");return s;}
  public static void Sample(string data,string session,DateTime utc,bool running){if(!Regex.IsMatch(session??"",@"^[A-Za-z0-9_-]{1,64}$")||utc.Kind!=DateTimeKind.Utc)throw new Exception("游玩采样参数无效。");string file=FileAt(data);LauncherNativeState.Locked(file,()=>{var s=Read(file);if(s.session!=session){s.session=session;s.sessionSeconds=0;s.lastTicks=utc.Ticks;s.running=running;}else {double seconds=(utc.Ticks-s.lastTicks)/(double)TimeSpan.TicksPerSecond;if(s.running&&seconds>0&&seconds<=15){DateTime start=new DateTime(s.lastTicks,DateTimeKind.Utc);while(start<utc){DateTime local=start.ToLocalTime();DateTime boundary=local.Date.AddDays(1).ToUniversalTime();DateTime end=boundary<utc?boundary:utc;if(end<=start)end=utc;string day=local.ToString("yyyy-MM-dd");double chunk=(end-start).TotalSeconds,current;s.days.TryGetValue(day,out current);s.days[day]=current+chunk;s.totalSeconds+=chunk;s.sessionSeconds+=chunk;start=end;}}s.lastTicks=utc.Ticks;s.running=running;}LauncherNativeState.Write(file,s);return true;});}
  public static object Snapshot(string data){return SnapshotAt(data,DateTime.UtcNow);}
  public static object SnapshotAt(string data,DateTime utc){string file=FileAt(data);return LauncherNativeState.Locked(file,()=>{var s=Read(file);double today;s.days.TryGetValue(utc.ToLocalTime().ToString("yyyy-MM-dd"),out today);bool fresh=s.running&&utc.Ticks>=s.lastTicks&&utc.Ticks-s.lastTicks<=TimeSpan.FromSeconds(15).Ticks;double threshold=s.reminderDay==utc.ToLocalTime().ToString("yyyy-MM-dd")?s.nextReminder:s.reminderMinutes;string tracking=fresh?"running":Waiting(data,utc)?"waiting":s.running?"lost":"stopped";return (object)new{todaySeconds=(long)today,totalSeconds=(long)s.totalSeconds,running=fresh,sessionSeconds=(long)s.sessionSeconds,reminderMinutes=s.reminderMinutes,reminderDue=s.reminderMinutes>0&&today>=threshold*60,tracking=tracking,message=tracking=="waiting"?"正在等待真实游戏进程；尚未开始计时":fresh?"正在按实际游戏进程记录":"仅统计从启动器发起的游戏；后台计时异常不会补算离线时长"};});}
  static bool Waiting(string data,DateTime utc){string directory=Path.Combine(data,"playtime");LauncherMaintenance.NoReparse(directory);if(!Directory.Exists(directory))return false;foreach(string file in Directory.GetFiles(directory,"launch-*.json").Take(100)){try{var r=LauncherNativeState.Read<PlaytimeRequest>(file,()=>null);if(r!=null&&Regex.IsMatch(r.nonce??"","^[a-f0-9]{32}$")&&utc.Ticks>=r.created&&utc.Ticks-r.created<=TimeSpan.FromSeconds(123).Ticks)return true;}catch{}}return false;}
  public static object Settings(string data,Dictionary<string,object> payload){string file=FileAt(data);return LauncherNativeState.Locked(file,()=>{var s=Read(file);object value;bool dismiss=payload.TryGetValue("dismissReminder",out value)&&value is bool&&(bool)value;if(dismiss){s.reminderDay=DateTime.Now.ToString("yyyy-MM-dd");double today;s.days.TryGetValue(s.reminderDay,out today);s.nextReminder=s.reminderMinutes==0?0:(Math.Floor(today/(60*s.reminderMinutes))+1)*s.reminderMinutes;}else {if(!payload.TryGetValue("reminderMinutes",out value)||!(value is int)||((int)value!=0&&((int)value<15||(int)value>480)))throw new Exception("提醒间隔须为 0（关闭）或 15–480 分钟的整数。");s.reminderMinutes=(int)value;s.reminderDay=null;s.nextReminder=s.reminderMinutes;}LauncherNativeState.Write(file,s);return (object)new{message=dismiss?"已关闭本次提醒；下一提醒按累计游玩时间计算。":"游玩提醒间隔已保存。"};});}
  static string RequestFile(string data,string nonce){if(!Regex.IsMatch(nonce??"",@"^[a-f0-9]{32}$"))throw new Exception("计时会话标识无效。");return Path.Combine(data,"playtime","launch-"+nonce+".json");}
  public static string Start(Engine e){if(e.TestMode)throw new Exception("测试模式禁止真实计时子进程。");string nonce=Guid.NewGuid().ToString("N"),file=RequestFile(e.Data,nonce);LauncherNativeState.Write(file,new PlaytimeRequest{game=e.Game,nonce=nonce,created=DateTime.UtcNow.AddSeconds(-3).Ticks});try{using(var worker=ManagedBackgroundWorker.Start("--playtime-watch",e.Data,nonce)){}return "已启动独立游玩计时；关闭启动器后仍统计本次游戏。";}catch{File.Delete(file);return "游戏启动请求已发送，但独立计时未启动；不会虚构游玩时间。";}}
  static Process Find(string game,long after){foreach(string name in new[]{"ProjectZomboid64","ProjectZomboid32","java","javaw"}){Process found=null;foreach(var p in Process.GetProcessesByName(name)){try{string image=p.MainModule.FileName;bool matches=name.StartsWith("ProjectZomboid",StringComparison.Ordinal)?string.Equals(Path.GetFullPath(image),Path.Combine(Path.GetFullPath(game),name+".exe"),StringComparison.OrdinalIgnoreCase):GameProcessGuard.ReadJavaRole(game,name,image,p)==JavaProcessRole.Client;if(found==null&&matches&&!p.HasExited&&p.StartTime.ToUniversalTime().Ticks>=after){found=p;continue;}}catch{}p.Dispose();}if(found!=null)return found;}return null;}
  public static int Watch(string data,string nonce){string file=RequestFile(data,nonce);bool held=false;Mutex mutex=null;try{var r=LauncherNativeState.Read<PlaytimeRequest>(file,()=>null);if(r==null||r.nonce!=nonce||DateTime.UtcNow.Ticks-r.created<0||DateTime.UtcNow.Ticks-r.created>TimeSpan.FromSeconds(130).Ticks||!GameDiscovery.IsGameFolder(r.game))return 2;mutex=new Mutex(false,"Local\\OrangePlaytime-"+DlssInstaller.Hash(Encoding.UTF8.GetBytes(Path.GetFullPath(r.game).ToUpperInvariant())));try{held=mutex.WaitOne(0);}catch(AbandonedMutexException){held=true;}if(!held)return 0;Process game=null;var wait=Stopwatch.StartNew();while(wait.Elapsed.TotalSeconds<120&&game==null){game=Find(r.game,r.created);if(game==null)Thread.Sleep(1000);}if(game==null)return 3;using(game){Sample(data,nonce,DateTime.UtcNow,true);while(!game.WaitForExit(1000))Sample(data,nonce,DateTime.UtcNow,true);Sample(data,nonce,DateTime.UtcNow,false);}return 0;}catch{return 1;}finally{if(held)mutex.ReleaseMutex();if(mutex!=null)mutex.Dispose();try{LauncherMaintenance.NoReparse(file);if(File.Exists(file))File.Delete(file);}catch{}}}
 }
}
